### 3.2 Agent Interface (`src/agents/types.ts`)

```typescript
import { z } from 'zod';

// ── Agent Capability Flags ──
export interface AgentCapability {
  supportsModel: boolean;        // Can accept --model param
  supportsJsonOutput: boolean;   // Can return structured JSON
  supportsStreaming: boolean;    // Supports stream output
  supportsSandbox: boolean;      // Has sandbox/safety modes
  supportsStdinPipe: boolean;    // Can receive context via stdin
  supportsSessionResume: boolean; // Can resume previous sessions
}

// ── Execution Options ──
export interface ExecutionOptions {
  prompt: string;
  model?: string;                // Override model for this request
  timeout?: number;              // ms, default from config
  cwd?: string;                  // Working directory
  context?: string;              // Additional context piped via stdin
  sandbox?: 'read-only' | 'write' | 'full';
  outputFormat?: 'text' | 'json';
}

// ── Agent Response ──
export interface AgentResponse {
  agent: string;                 // Agent identifier (e.g., "claude", "codex")
  model: string;                 // Model actually used
  content: string;               // Response text
  raw?: unknown;                 // Raw JSON if available
  durationMs: number;            // Execution time
  exitCode: number;              // Process exit code
  error?: string;                // Error message if failed
  truncated?: boolean;           // Whether output was truncated
}

// ── Agent Interface ──
export interface IAgent {
  readonly id: string;           // Unique identifier: "claude" | "codex" | "gemini" | "copilot"
  readonly displayName: string;  // Human-readable name
  readonly cliCommand: string;   // Binary name to execute
  readonly capabilities: AgentCapability;

  /** Check if this agent's CLI is available on the system */
  isAvailable(): Promise<boolean>;

  /** Get the list of supported models from config */
  getModels(): AgentModelConfig[];

  /** Get the default model for this agent */
  getDefaultModel(): string;

  /** Execute a prompt and return the response */
  execute(options: ExecutionOptions): Promise<AgentResponse>;

  /** Build the CLI argument array for a given execution */
  buildCommand(options: ExecutionOptions): { args: string[]; env?: Record<string, string> };
}

// ── Model Config (loaded from YAML) ──
export interface AgentModelConfig {
  id: string;                    // e.g., "claude-sonnet-4"
  name: string;                  // e.g., "Claude Sonnet 4"
  isDefault?: boolean;
  tier?: 'fast' | 'balanced' | 'powerful';
  contextWindow?: number;
  notes?: string;
}
```

### 3.3 Agent Registry and Detection (`src/agents/registry.ts`)

The registry is responsible for three tasks: (1) detecting which CLIs are installed, (2) registering agent instances, and (3) excluding the caller agent to prevent recursive calls.

```typescript
// Conceptual structure
export class AgentRegistry {
  private agents: Map<string, IAgent> = new Map();
  private excludedAgentId: string | null = null;

  /** Detect installed CLI agents and register them */
  async initialize(): Promise<void> {
    const detectors: Array<[string, () => IAgent]> = [
      ['claude',  () => new ClaudeAgent(config)],
      ['codex',   () => new CodexAgent(config)],
      ['gemini',  () => new GeminiAgent(config)],
      ['copilot', () => new CopilotAgent(config)],
    ];

    for (const [id, factory] of detectors) {
      const agent = factory();
      if (await agent.isAvailable()) {
        this.agents.set(id, agent);
      }
    }

    // Detect and exclude the calling agent
    this.excludedAgentId = this.detectCaller();
  }

  /** Identify which agent (if any) invoked this MCP server */
  private detectCaller(): string | null {
    // Claude Code sets CLAUDECODE=1
    if (process.env.CLAUDECODE === '1') return 'claude';

    // Copilot CLI sets specific env vars
    if (process.env.COPILOT_CLI) return 'copilot';

    // Codex sets its own marker
    if (process.env.CODEX_SANDBOX_TYPE) return 'codex';

    // Gemini sets GEMINI_CLI
    if (process.env.GEMINI_CLI) return 'gemini';

    // Also check process.env._ (last executed command)
    const lastCmd = process.env._ || '';
    if (lastCmd.includes('claude')) return 'claude';
    if (lastCmd.includes('copilot')) return 'copilot';
    if (lastCmd.includes('codex')) return 'codex';
    if (lastCmd.includes('gemini')) return 'gemini';

    return null;
  }

  /** Get available agents (excluding caller) */
  getAvailableAgents(): IAgent[] {
    return Array.from(this.agents.values())
      .filter(a => a.id !== this.excludedAgentId);
  }

  getAgent(id: string): IAgent | undefined {
    if (id === this.excludedAgentId) return undefined;
    return this.agents.get(id);
  }

  getExcludedAgent(): string | null {
    return this.excludedAgentId;
  }
}
```

**Critical insight on recursive call prevention**: The `CLAUDECODE=1` environment variable is set in the current session (confirmed via `env` inspection). When the MCP server spawns `claude -p`, it must unset this variable:

```typescript
// In ClaudeAgent.buildCommand():
buildCommand(options: ExecutionOptions): { args: string[]; env?: Record<string, string> } {
  const args = ['-p', options.prompt, '--output-format', 'json'];
  if (options.model) args.push('--model', options.model);

  return {
    args,
    env: {
      ...process.env,
      CLAUDECODE: '',  // Unset to prevent nesting detection
    }
  };
}
```

