### 3.5 Base Agent Implementation (`src/agents/base-agent.ts`)

The abstract base handles common subprocess execution logic:

```typescript
export abstract class BaseAgent implements IAgent {
  abstract readonly id: string;
  abstract readonly displayName: string;
  abstract readonly cliCommand: string;
  abstract readonly capabilities: AgentCapability;

  constructor(protected config: AgentConfigSection) {}

  async isAvailable(): Promise<boolean> {
    try {
      const path = await which(this.cliCommand, { nothrow: true });
      return path !== null;
    } catch {
      return false;
    }
  }

  getModels(): AgentModelConfig[] {
    return this.config.models || [];
  }

  getDefaultModel(): string {
    const defaultModel = this.config.models?.find(m => m.isDefault);
    return defaultModel?.id || this.config.defaultModel || '';
  }

  abstract buildCommand(options: ExecutionOptions): {
    args: string[];
    env?: Record<string, string>;
  };

  async execute(options: ExecutionOptions): Promise<AgentResponse> {
    const startTime = Date.now();
    const { args, env } = this.buildCommand(options);
    const timeout = options.timeout || this.config.timeout || 120_000;

    try {
      const result = await execAsync(this.cliCommand, args, {
        env,
        cwd: options.cwd || process.cwd(),
        timeout,
        stdin: options.context,  // pipe context if provided
        maxOutputChars: this.config.maxOutputChars || 16_000,
      });

      return {
        agent: this.id,
        model: options.model || this.getDefaultModel(),
        content: this.parseOutput(result.stdout),
        raw: this.parseJsonSafe(result.stdout),
        durationMs: Date.now() - startTime,
        exitCode: result.exitCode,
        truncated: result.truncated,
      };
    } catch (error) {
      return {
        agent: this.id,
        model: options.model || this.getDefaultModel(),
        content: '',
        durationMs: Date.now() - startTime,
        exitCode: -1,
        error: this.formatError(error),
      };
    }
  }

  protected abstract parseOutput(stdout: string): string;
}
```

